const rows = $input.all();
if (rows.length === 0) {
  throw new Error('The uploaded Excel file has no data rows. Add at least one product row below the header.');
}

const normalizeHeader = (value) => String(value ?? '')
  .replace(/^\uFEFF/, '')
  .trim()
  .toLowerCase()
  .replace(/[\s-]+/g, '_');

const firstRow = rows[0].json ?? {};
const headers = Object.keys(firstRow);
const variantKey = headers.find((key) => normalizeHeader(key) === 'variant_label');
const productKey = headers.find((key) => normalizeHeader(key) === 'product_name');

if (!variantKey || !productKey) {
  throw new Error(
    'Missing required Excel headers. The first worksheet must contain exactly these columns: variant_label and product_name. Found: ' + headers.join(', ')
  );
}

return rows.map((item, index) => {
  const row = item.json ?? {};
  const variantValue = row[variantKey] ?? '';
  const productValue = row[productKey] ?? '';
  const variantLabel = String(variantValue).trim();
  const productName = String(productValue).trim();

  if (!productName) {
    throw new Error('product_name is blank at Excel data row ' + (index + 2) + '. Fill every product_name cell and upload again.');
  }

  const searchQuery = [productName, variantLabel].filter(Boolean).join(' ').replace(/\s+/g, ' ').trim();
  return {
    json: {
      variant_label: variantLabel,
      product_name: productName,
      search_query: searchQuery,
      input_row: index + 2,
    },
    pairedItem: { item: index },
  };
});

const original = $('Prepare Search Query').item.json;
let payload = $json.body ?? $json;
const statusCode = Number($json.statusCode ?? 0);

if (typeof payload === 'string') {
  try {
    payload = JSON.parse(payload);
  } catch (error) {
    return {
      json: {
        variant_label: original.variant_label,
        product_name: original.product_name,
        image_url: '',
        image_title: '',
        image_source_url: '',
        image_status: 'SEARCH_ERROR',
        search_query: original.search_query,
        input_row: original.input_row,
        search_error: statusCode ? 'SearXNG returned HTTP ' + statusCode + ' (JSON response may be disabled).' : 'SearXNG did not return JSON. Enable the json search format in SearXNG settings.',
      },
    };
  }
}

if (payload && payload.data && Array.isArray(payload.data.results)) {
  payload = payload.data;
}

const results = Array.isArray(payload?.results) ? payload.results : [];
const firstImage = results.find((result) =>
  typeof result?.img_src === 'string' && /^https?:\/\//i.test(result.img_src.trim())
);

let imageStatus = firstImage ? 'FOUND' : 'NOT_FOUND';
let searchError = '';
if (statusCode >= 400) {
  imageStatus = 'SEARCH_ERROR';
  searchError = 'SearXNG returned HTTP ' + statusCode;
} else if (!Array.isArray(payload?.results)) {
  imageStatus = 'SEARCH_ERROR';
  searchError = 'Unexpected SearXNG response: results[] was missing. Ensure format=json is enabled.';
}

return {
  json: {
    variant_label: original.variant_label,
    product_name: original.product_name,
    image_url: firstImage?.img_src ?? '',
    image_title: firstImage?.title ?? '',
    image_source_url: firstImage?.url ?? '',
    image_status: imageStatus,
    search_query: original.search_query,
    input_row: original.input_row,
    search_error: searchError,
  },
};
